// Shareable links carry the whole schema in the URL hash, so nothing is sent to a server.
//   #z.<base64url(deflate-raw(utf8))>   compressed (current format)
//   #u.<base64url(utf8)>                 uncompressed fallback for browsers without CompressionStream
//   #<base64(encodeURIComponent(sql))>   legacy links generated by the first version

const COMPRESSED = 'z.';
const PLAIN = 'u.';

function bytesToBase64Url(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64UrlToBytes(text: string): Uint8Array {
  const b64 = text.replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

async function pipeThrough(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const piped = new Blob([bytes as BlobPart]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(piped).arrayBuffer());
}

/** Hash fragment (without "#") that encodes `sql` */
export async function encodeShareHash(sql: string): Promise<string> {
  const bytes = new TextEncoder().encode(sql);
  if (typeof CompressionStream === 'undefined') {
    return PLAIN + bytesToBase64Url(bytes);
  }
  return COMPRESSED + bytesToBase64Url(await pipeThrough(bytes, new CompressionStream('deflate-raw')));
}

/** SQL stored in a hash fragment (with or without "#"), or null when it isn't a share link */
export async function decodeShareHash(hash: string): Promise<string | null> {
  const value = hash.replace(/^#/, '');
  if (!value) return null;
  try {
    if (value.startsWith(COMPRESSED)) {
      const bytes = await pipeThrough(base64UrlToBytes(value.slice(COMPRESSED.length)), new DecompressionStream('deflate-raw'));
      return new TextDecoder().decode(bytes);
    }
    if (value.startsWith(PLAIN)) {
      return new TextDecoder().decode(base64UrlToBytes(value.slice(PLAIN.length)));
    }
    return decodeURIComponent(atob(value)) || null;
  } catch {
    return null;
  }
}
